head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00202.xml";
// 전역 변수 선언
scwin.vKisCd = ""; // 기업코드

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정) 
 */

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {

    scwin.init();

};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {
};

// 일반 함수
/**
 *  화면 초기화
 */
scwin.init = function() {
    scwin.search();
};

/**
 *  데이터셋 초기화
 */
scwin.initDs = function() {
    dlt_businessObjectListRes.setData([]);
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    scwin.vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();

    if (scwin.vKisCd === "") {
        return false;
    }

    return true;
};

/**
 * 사업목적 조회
 */
scwin.search = async function() {

    scwin.initDs();

    if (!scwin.chkValid()) {
        return;
    }

    const kisCd = scwin.vKisCd;
    $c.sbm.setAction(sbm_businessObject, "/api/listing/nice/company-status/" + kisCd + "/business-object");
    const res = await $c.sbm.execute(sbm_businessObject);
    dlt_businessObjectListRes.setJSON(res.responseJSON.body);

};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {

    if (dlt_businessObjectListRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    const options = {
        fileName : "사업목적",
        sheetName : "사업목적"
    };

    const infoArray = {};

    grd_bzPurps.advancedExcelDownload(options, infoArray);

};
